// Billed is the declared query billed: turns with their usage, not pinned.
var Billed billedQuery

// billedQuery runs the query billed; its row is BilledRow.
type billedQuery struct{}

// BilledRow is a row of the query billed: a copy of each component of its "all" that holds a value.
type BilledRow struct {
	Turn  TurnValue
	Usage UsageValue
}

// Iter runs the query billed and returns its answer as a sequence of each entity and its row, in the order of the
// engine's answer. The query runs before Iter returns, so an error of e, ecr.ErrCold and ecr.ErrQuery among them,
// comes before any yield. A loop body that moves e panics with an *IterError at the next step.
func (billedQuery) Iter(e ecr.Engine) (iter.Seq2[ecr.ID, BilledRow], error) {
	return iterRows(e, QIDBilled, func(id ecr.ID, r *BilledRow) error {
		if err := readValue(e, id, CIDTurn, &r.Turn); err != nil {
			return err
		}
		return readValue(e, id, CIDUsage, &r.Usage)
	})
}

// QID returns QIDBilled.
func (billedQuery) QID() ecr.QID { return QIDBilled }

// decoder is the pointer type of a generated value type: Decode sets the value from its codec bytes.
type decoder[T any] interface {
	*T
	Decode(b []byte) error
}

// getValue reads component c of id from e and decodes it. An error that matches ecr.ErrAbsent answers the zero T,
// false and nil; every other error is returned.
func getValue[T any, P decoder[T]](e ecr.Engine, id ecr.ID, c ecr.CID) (T, bool, error) {
	var v T
	b, err := e.Get(id, c, nil)
	if errors.Is(err, ecr.ErrAbsent) {
		return v, false, nil
	}
	if err != nil {
		return v, false, err
	}
	if err := P(&v).Decode(b); err != nil {
		return v, false, err
	}
	return v, true, nil
}

// has reports whether id holds component or tag c. An error that matches ecr.ErrAbsent answers false and nil.
func has(e ecr.Engine, id ecr.ID, c ecr.CID) (bool, error) {
	_, err := e.Get(id, c, nil)
	switch {
	case err == nil:
		return true, nil
	case errors.Is(err, ecr.ErrAbsent):
		return false, nil
	}
	return false, err
}

// IterError is the panic value of a sequence of Iter whose engine moved or failed during the loop. At is the engine's
// At() when the query ran and Now its At() at the failing step; Err is the error of the step's read, or nil when the
// engine moved.
type IterError struct {
	QID ecr.QID
	At  uint64
	Now uint64
	Err error
}

// Error describes the failed step.
func (e *IterError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("llm: iteration of query %d at seq %d: %v", e.QID, e.At, e.Err)
	}
	return fmt.Sprintf("llm: iteration of query %d at seq %d: the engine moved to seq %d", e.QID, e.At, e.Now)
}

// Unwrap returns Err.
func (e *IterError) Unwrap() error { return e.Err }

// iterRows runs query q on e and returns a sequence of each entity of its answer and the row that read fills. The
// query runs before iterRows returns; each step panics with an *IterError when e has moved or read fails.
func iterRows[R any](e ecr.Engine, q ecr.QID, read func(id ecr.ID, r *R) error) (iter.Seq2[ecr.ID, R], error) {
	at := e.At()
	var a ecr.Answer
	if err := e.Query(q, nil, &a); err != nil {
		return nil, err
	}
	return func(yield func(ecr.ID, R) bool) {
		for _, id := range a.IDs {
			if now := e.At(); now != at {
				panic(&IterError{QID: q, At: at, Now: now})
			}
			var r R
			if err := read(id, &r); err != nil {
				panic(&IterError{QID: q, At: at, Now: at, Err: err})
			}
			if !yield(id, r) {
				return
			}
		}
	}, nil
}

// iterValues runs query q on e and returns a sequence of each entity of its answer and a copy of its component c.
func iterValues[T any, P decoder[T]](e ecr.Engine, q ecr.QID, c ecr.CID) (iter.Seq2[ecr.ID, T], error) {
	return iterRows(e, q, func(id ecr.ID, v *T) error { return readValue[T, P](e, id, c, v) })
}

// scanValues calls f with each entity of kind k above after in s that holds component c, and a copy of its c, in
// eid order. A value that does not decode stops the scan with an error that names the entity; an error of s or of
// f is returned unchanged.
func scanValues[T any, P decoder[T]](s ecr.Scanner, k ecr.Kind, c ecr.CID, after ecr.ID, f func(id ecr.ID, v T) error) error {
	return s.Scan(k, c, after, func(_ uint64, src ecr.RowSource) error {
		var r ecr.Row
		for {
			ok, err := src.Next(&r)
			if err != nil || !ok {
				return err
			}
			var v T
			if err := P(&v).Decode(r.Value); err != nil {
				return fmt.Errorf("llm: scan of %v: %w", r.Entity, err)
			}
			if err := f(r.Entity, v); err != nil {
				return err
			}
		}
	})
}

// readValue reads component c of id from e into v. Every error of e, ecr.ErrAbsent among them, is returned.
func readValue[T any, P decoder[T]](e ecr.Engine, id ecr.ID, c ecr.CID, v *T) error {
	b, err := e.Get(id, c, nil)
	if err != nil {
		return err
	}
	return P(v).Decode(b)
}
